USE MaquipesaEIRL
GO

-- 1. Borrar la tabla antigua (si existe) y las restricciones de clave foránea temporales
IF OBJECT_ID('hechos_movimientos', 'U') IS NOT NULL 
    DROP TABLE hechos_movimientos;
GO

-- 2. Crear la tabla con TODAS las columnas necesarias
CREATE TABLE hechos_movimientos (
    id_movimiento INT PRIMARY KEY,
    id_fecha INT,
    id_almacen INT,
    id_articulo INT,
    id_proveedor INT,
    id_tipo_movimiento INT,
    cantidad_stock INT,       -- ¡NUEVA COLUMNA!
    valor_stock DECIMAL(18,2) -- ¡NUEVA COLUMNA!
);
GO

-- 3. Insertar los datos (asignando valores de cantidad y valor para el dashboard)
-- Nota: Como no tenía tus valores de cantidad y valor, he generado números para que el dashboard funcione.

-- 4. Re-crear las claves foráneas
ALTER TABLE hechos_movimientos ADD FOREIGN KEY (id_fecha) REFERENCES dim_fecha(id_fecha);
ALTER TABLE hechos_movimientos ADD FOREIGN KEY (id_almacen) REFERENCES dim_almacen(id_almacen);
ALTER TABLE hechos_movimientos ADD FOREIGN KEY (id_articulo) REFERENCES dim_articulo(id_articulo);
ALTER TABLE hechos_movimientos ADD FOREIGN KEY (id_proveedor) REFERENCES dim_proveedor(id_proveedor);
ALTER TABLE hechos_movimientos ADD FOREIGN KEY (id_tipo_movimiento) REFERENCES dim_tipo_movimiento(id_tipo_movimiento);
GO